1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .next-list { display: flex; flex-direction: column; gap: 8px; }
58	  .board-wrap { position: relative; }
59	  .game-over {
60	    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
61	    background: rgba(17, 20, 24, .78); font-size: 24px; font-weight: 600; border-radius: 4px;
62	  }
63	  .p-I { background: var(--I) !important; }
64	  .p-O { background: var(--O) !important; }
65	  .p-T { background: var(--T) !important; }
66	  .p-S { background: var(--S) !important; }
67	  .p-Z { background: var(--Z) !important; }
68	  .p-J { background: var(--J) !important; }
69	  .p-L { background: var(--L) !important; }
70	  button {
71	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
72	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
73	  }
74	  button:hover { border-color: var(--muted); }
75	  .keys { color: var(--muted); font-size: 13px; }
76	</style>
77	</head>
78	<body>
79	<div class="game">
80	  <div class="board-wrap">
81	    <div class="board" data-testid="board" id="board"></div>
82	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
83	  </div>
84	  <div class="side">
85	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
86	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
87	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
88	    <div class="box"><div class="label">Hold</div><div class="preview" data-testid="hold-piece" data-piece="" id="hold"></div></div>
89	    <div class="box"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
90	    <button id="restart" type="button">New game</button>
91	    <div class="keys">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop<br>C hold</div>
92	  </div>
93	</div>
94	<script>
95	(function () {
96	  "use strict";
97	
98	  var ROWS = 20, COLS = 10;
99	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
100	
101	  // Spawn shapes as [row, col] offsets from the piece origin.
102	  var SHAPES = {
103	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
104	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
105	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
106	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
107	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
108	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
109	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
110	  };
111	  // Side length of the square each shape rotates within.
112	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
113	  var SPAWN_COL = 3;
114	  // Level rule (project decision): level starts at 1 and rises by one for every
115	  // LINES_PER_LEVEL lines cleared; it never goes down. Gravity interval in ms is
116	  // max(MIN_GRAVITY_MS, BASE_GRAVITY_MS - (level - 1) * GRAVITY_STEP_MS).
117	  // __tetris.tick(n) always advances exactly n gravity steps, whatever the level.
118	  var LINES_PER_LEVEL = 10;
119	  var BASE_GRAVITY_MS = 1000;
120	  var GRAVITY_STEP_MS = 100;
121	  var MIN_GRAVITY_MS = 100;
122	  // Hold rule (project decision): one slot. Holding with an empty slot sets the
123	  // falling piece aside and spawns the next one; otherwise it swaps with the held
124	  // piece, which enters at the spawn position. One hold per piece: a second hold
125	  // is refused until a piece locks.
126	  // Preview rule (project decision): show only the next piece, in its board colour.
127	  var PREVIEW_COUNT = 1;
128	
129	  // Locking rule (project decision): a gravity step that cannot move the piece
130	  // down counts one lock tick; the piece locks on the LOCK_TICKS-th tick.
131	  // Left/right while resting restarts the delay, at most MAX_LOCK_RESETS times
132	  // per piece. Soft drop on a resting piece restarts it too, from the same
133	  // per-piece allowance. Hard drop locks at once.
134	  var LOCK_TICKS = 2;
135	  var MAX_LOCK_RESETS = 3;
136	  // Rotation tries these sideways shifts, in order, until one fits.
137	  var KICKS = [0, -1, 1, -2, 2];
138	
139	  // Scoring rule (project decision): a clear scores CLEAR_POINTS[rows] x level.
140	  // Clearing rows together must always beat clearing them one at a time.
141	  // Soft drop scores 1 per cell moved by the player (gravity scores nothing);
142	  // hard drop scores 2 per cell dropped. Drop points are not multiplied.
143	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
144	  var SOFT_DROP_POINTS = 1;
145	  var HARD_DROP_POINTS = 2;
146	
147	  var state = {
148	    board: [],      // ROWS x COLS, "" or piece letter
149	    current: null,  // { type, row, col, shape, lockTicks, lockResets }
150	    next: [],
151	    hold: null,     // held piece letter or null
152	    canHold: true,
153	    score: 0,
154	    level: 1,
155	    lines: 0,
156	    status: "running"
157	  };
158	
159	  // ---- core logic ----
160	
161	  function emptyBoard() {
162	    var b = [];
163	    for (var r = 0; r < ROWS; r++) {
164	      var row = [];
165	      for (var c = 0; c < COLS; c++) row.push("");
166	      b.push(row);
167	    }
168	    return b;
169	  }
170	
171	  function randomType() {
172	    return TYPES[Math.floor(Math.random() * TYPES.length)];
173	  }
174	
175	  function cellsOf(piece, dRow, dCol) {
176	    return piece.shape.map(function (o) {
177	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
178	    });
179	  }
180	
181	  function fits(piece, dRow, dCol) {
182	    return cellsOf(piece, dRow, dCol).every(function (p) {
183	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
184	    });
185	  }
186	
187	  function dropInterval() {
188	    return Math.max(MIN_GRAVITY_MS, BASE_GRAVITY_MS - (state.level - 1) * GRAVITY_STEP_MS);
189	  }
190	
191	  function spawn() {
192	    var type = state.next.length ? state.next.shift() : randomType();
193	    while (state.next.length < PREVIEW_COUNT) state.next.push(randomType());
194	    spawnType(type);
195	  }
196	
197	  function spawnType(type) {
198	    var piece = { type: type, row: 0, col: SPAWN_COL, shape: SHAPES[type], lockTicks: 0, lockResets: 0 };
199	    // Game over: the new piece has nowhere to go. It is not placed.
200	    if (!fits(piece, 0, 0)) {
201	      state.current = null;
202	      state.status = "gameover";
203	      return;
204	    }
205	    state.current = piece;
206	  }
207	
208	  function lock() {
209	    var piece = state.current;
210	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
211	    state.current = null;
212	    state.canHold = true;
213	    clearLines();
214	    spawn();
215	  }
216	
217	  // Remove every full row; rows above drop down. Scores the clear.
218	  function clearLines() {
219	    var kept = state.board.filter(function (row) {
220	      return row.some(function (t) { return t === ""; });
221	    });
222	    var cleared = ROWS - kept.length;
223	    if (!cleared) return;
224	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
225	    state.board = kept;
226	    var before = Math.floor(state.lines / LINES_PER_LEVEL);
227	    state.lines += cleared;
228	    state.score += CLEAR_POINTS[cleared] * state.level;
229	    var gained = Math.floor(state.lines / LINES_PER_LEVEL) - before;
230	    if (gained > 0) {
231	      state.level += gained;
232	      restartTimer();
233	    }
234	  }
235	
236	  function tryMove(dRow, dCol) {
237	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
238	    state.current.row += dRow;
239	    state.current.col += dCol;
240	    if (dRow > 0) state.current.lockTicks = 0;
241	    return true;
242	  }
243	
244	  // If the lock delay is running, restart it (capped per piece).
245	  function resetLockDelay(piece) {
246	    if (piece.lockTicks > 0 && piece.lockResets < MAX_LOCK_RESETS) {
247	      piece.lockResets++;
248	      piece.lockTicks = 0;
249	    }
250	  }
251	
252	  function shift(dCol) {
253	    var piece = state.current;
254	    if (!tryMove(0, dCol)) return;
255	    resetLockDelay(piece);
256	  }
257	
258	  function rotateCW() {
259	    var piece = state.current;
260	    if (!piece || piece.type === "O") return;
261	    var n = BOX[piece.type];
262	    var turned = {
263	      type: piece.type, row: piece.row, col: piece.col,
264	      shape: piece.shape.map(function (o) { return [o[1], n - 1 - o[0]]; })
265	    };
266	    for (var i = 0; i < KICKS.length; i++) {
267	      if (fits(turned, 0, KICKS[i])) {
268	        piece.shape = turned.shape;
269	        piece.col += KICKS[i];
270	        return;
271	      }
272	    }
273	  }
274	
275	  // One gravity step. The timer and __tetris.tick both call this.
276	  function gravityStep() {
277	    if (state.status !== "running" || !state.current) return;
278	    if (tryMove(1, 0)) return;
279	    state.current.lockTicks++;
280	    if (state.current.lockTicks >= LOCK_TICKS) lock();
281	  }
282	
283	  var actions = {
284	    left: function () { if (state.current) shift(-1); },
285	    right: function () { if (state.current) shift(1); },
286	    rotateCW: rotateCW,
287	    softDrop: function () {
288	      if (!state.current) return;
289	      if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
290	      else resetLockDelay(state.current);
291	    },
292	    hardDrop: function () {
293	      if (!state.current) return;
294	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
295	      lock();
296	    },
297	    hold: function () {
298	      if (!state.current || !state.canHold) return;
299	      var type = state.current.type;
300	      state.canHold = false;
301	      if (state.hold) {
302	        var held = state.hold;
303	        state.hold = type;
304	        spawnType(held);
305	      } else {
306	        state.hold = type;
307	        spawn();
308	      }
309	    }
310	  };
311	
312	  function doAction(name) {
313	    if (state.status !== "running" || !actions[name]) return;
314	    actions[name]();
315	    render();
316	  }
317	
318	  function newGame(queue) {
319	    state.board = emptyBoard();
320	    state.score = 0;
321	    state.level = 1;
322	    state.lines = 0;
323	    state.hold = null;
324	    state.canHold = true;
325	    state.status = "running";
326	    state.next = Array.isArray(queue) ? queue.slice() : [];
327	    spawn();
328	    restartTimer();
329	    render();
330	  }
331	
332	  // ---- rendering (synchronous) ----
333	
334	  var boardEl = document.getElementById("board");
335	  var previewEl = document.getElementById("preview");
336	  var scoreEl = document.getElementById("score");
337	  var levelEl = document.getElementById("level");
338	  var linesEl = document.getElementById("lines");
339	  var gameOverEl = document.getElementById("game-over");
340	  var holdEl = document.getElementById("hold");
341	  var cellEls = [];
342	  var holdCells = [];
343	  for (var h = 0; h < 8; h++) holdCells.push(holdEl.appendChild(document.createElement("div")));
344	
345	  (function buildDom() {
346	    for (var r = 0; r < ROWS; r++) {
347	      var row = [];
348	      for (var c = 0; c < COLS; c++) {
349	        var el = document.createElement("div");
350	        el.className = "cell";
351	        el.setAttribute("data-testid", "cell");
352	        el.setAttribute("data-row", String(r));
353	        el.setAttribute("data-col", String(c));
354	        el.setAttribute("data-filled", "false");
355	        el.setAttribute("data-piece", "");
356	        boardEl.appendChild(el);
357	        row.push(el);
358	      }
359	      cellEls.push(row);
360	    }
361	  })();
362	
363	  // One preview item per previewed piece, drawn in its board colour.
364	  function previewItem(type) {
365	    var item = document.createElement("div");
366	    item.className = "preview";
367	    item.setAttribute("data-testid", "next-piece-item");
368	    item.setAttribute("data-piece", type);
369	    var cells = [];
370	    for (var i = 0; i < 8; i++) cells.push(item.appendChild(document.createElement("div")));
371	    SHAPES[type].forEach(function (o) { paint(cells[o[0] * 4 + o[1]], type); });
372	    return item;
373	  }
374	
375	  function paint(el, type) {
376	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
377	  }
378	
379	  function render() {
380	    var view = state.board.map(function (row) { return row.slice(); });
381	    if (state.current) {
382	      cellsOf(state.current).forEach(function (p) {
383	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
384	      });
385	    }
386	    for (var r = 0; r < ROWS; r++) {
387	      for (var c = 0; c < COLS; c++) {
388	        var el = cellEls[r][c], t = view[r][c];
389	        el.setAttribute("data-filled", t ? "true" : "false");
390	        el.setAttribute("data-piece", t);
391	        paint(el, t);
392	      }
393	    }
394	    previewEl.textContent = "";
395	    state.next.slice(0, PREVIEW_COUNT).forEach(function (type) {
396	      if (SHAPES[type]) previewEl.appendChild(previewItem(type));
397	    });
398	    holdEl.setAttribute("data-piece", state.hold || "");
399	    holdCells.forEach(function (el) { paint(el, ""); });
400	    if (state.hold) SHAPES[state.hold].forEach(function (o) { paint(holdCells[o[0] * 4 + o[1]], state.hold); });
401	    gameOverEl.hidden = state.status !== "gameover";
402	    scoreEl.textContent = String(state.score);
403	    levelEl.textContent = String(state.level);
404	    linesEl.textContent = String(state.lines);
405	  }
406	
407	  // ---- timer ----
408	
409	  var timer = null;
410	  function onTimer() { gravityStep(); render(); }
411	  function restartTimer() {
412	    if (timer) clearInterval(timer);
413	    timer = setInterval(onTimer, dropInterval());
414	  }
415	
416	  // ---- input ----
417	
418	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop", c: "hold", C: "hold" };
419	  document.addEventListener("keydown", function (e) {
420	    var action = KEYS[e.key];
421	    if (!action) return;
422	    e.preventDefault();
423	    doAction(action);
424	  });
425	  document.getElementById("restart").addEventListener("click", function (e) {
426	    e.currentTarget.blur();
427	    newGame();
428	  });
429	
430	  // ---- test control surface ----
431	
432	  window.__tetris = {
433	    newGame: function (queue) { newGame(queue); },
434	    setQueue: function (queue) {
435	      state.next = Array.isArray(queue) ? queue.slice() : [];
436	      render();
437	    },
438	    setBoard: function (rows) {
439	      state.board = rows.map(function (line) {
440	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
441	      });
442	      render();
443	    },
444	    tick: function (n) {
445	      var steps = n === undefined ? 1 : n;
446	      for (var i = 0; i < steps; i++) gravityStep();
447	      render();
448	    },
449	    setLevel: function (n) {
450	      state.level = n;
451	      restartTimer();
452	      render();
453	    },
454	    input: function (action) { doAction(action); },
455	    getBoard: function () {
456	      return state.board.map(function (row) {
457	        return row.map(function (t) { return t || "."; }).join("");
458	      });
459	    },
460	    getState: function () {
461	      return {
462	        current: state.current
463	          ? { type: state.current.type, cells: cellsOf(state.current) }
464	          : null,
465	        next: state.next.slice(),
466	        score: state.score,
467	        level: state.level,
468	        dropInterval: dropInterval(),
469	        hold: state.hold,
470	        lines: state.lines,
471	        status: state.status
472	      };
473	    }
474	  };
475	
476	  newGame();
477	})();
478	</script>
479	</body>
480	</html>
481
